-- Run only in a disposable PG16 cluster after native263/264. Every synthetic row rolls back.
BEGIN;
SET LOCAL ROLE celebix_saas_owner;
SET LOCAL search_path=pg_catalog,saas;
SET LOCAL statement_timeout='30s';
CREATE TEMP TABLE store_tool_public_checks(name text PRIMARY KEY);
DO $test$
DECLARE
 st uuid:='a2640000-0000-4000-8000-000000000001';otherst uuid:='a2640000-0000-4000-8000-000000000011';
 pr uuid:='a2640000-0000-4000-8000-000000000002';
 p1 uuid:='a2640000-0000-4000-8000-000000000020';p2 uuid:='a2640000-0000-4000-8000-000000000021';
 v1 uuid:='a2640000-0000-4000-8000-000000000030';v2 uuid:='a2640000-0000-4000-8000-000000000031';v3 uuid:='a2640000-0000-4000-8000-000000000032';
 cart uuid:='a2640000-0000-4000-8000-000000000050';capture uuid:='a2640000-0000-4000-8000-000000000060';
 popup uuid:='a2640000-0000-4000-8000-000000000061';op uuid:=gen_random_uuid();
 n timestamptz:=date_trunc('milliseconds',transaction_timestamp());r record;job jsonb;lease uuid;jobid uuid;receipt jsonb;
 free saas.plans;growth saas.plans;store uuid;host text:='tool-264.qa.celebix.invalid';otherhost text:='tool-other-264.qa.celebix.invalid';
 engagement jsonb:='{"schemaVersion":1,"template":"minimal","heading":"Merhaba","body":"","buttonLabel":"Kaydet","delaySeconds":0,"repeatDays":7,"devices":{"desktop":true,"mobile":true},"collectMode":"email"}';
 widget jsonb:='{"schemaVersion":1,"enabled":true,"title":"İletişim","greeting":"Merhaba","buttonLabel":"Ulaşın","position":"bottom-right","icon":"message","theme":"brand","devices":{"desktop":true,"mobile":true},"pages":["home","products","categories","content","cart","search"],"whatsappMessage":"Merhaba","includeProductLink":true,"hours":{"enabled":false,"timeZone":"Europe/Istanbul","days":[1,2,3,4,5],"opensAt":"09:00","closesAt":"18:00","outsideBehavior":"message","outsideMessage":"Mesai dışındayız."},"channels":[{"type":"whatsapp","enabled":true,"label":"WhatsApp","value":"+905551112233"}]}';
 whatsapp jsonb:='{"schemaVersion":1,"enabled":true,"phone":"+905551112233","hidePrices":false,"hideAddToCart":false,"messageIntro":"Merhaba"}';
 creds jsonb:=jsonb_build_array(jsonb_build_object('keyId','qa264','digest',repeat('a',64)));
BEGIN
 SELECT * INTO STRICT free FROM saas.plans WHERE id='00000000-0000-4000-8000-000000000007';
 SELECT * INTO STRICT growth FROM saas.plans WHERE id='00000000-0000-4000-8000-000000000009';
 IF saas.commercial_plan_has_capability(free.id,'growth_tools')OR NOT saas.commercial_plan_has_capability(growth.id,'growth_tools')THEN RAISE EXCEPTION 'TOOL264_PACKAGE_FIXTURE';END IF;
 INSERT INTO saas.stores(id,name,slug,status,locale,currency,theme_key,created_at,updated_at) VALUES(st,'Licensed free fixture','tool-264','active','tr','TRY','hemenaku',n,n),(otherst,'Unlicensed growth fixture','tool-other-264','active','tr','TRY','hemenaku',n,n);
 INSERT INTO saas.principals(id,issuer,subject,email,email_verified,created_at,updated_at) VALUES(pr,'https://qa.celebix.invalid','tools264','tool264@qa.celebix.invalid',true,n,n);
 INSERT INTO saas.subscriptions VALUES(gen_random_uuid(),st,free.id,free.plan_code,free.version,'active',n-interval '1 day',NULL,n,n),(gen_random_uuid(),otherst,growth.id,growth.plan_code,growth.version,'active',n-interval '1 day',NULL,n,n);
 INSERT INTO saas.store_domains(id,store_id,hostname,hostname_type,status,is_primary,verified_at,created_at,updated_at) VALUES(gen_random_uuid(),st,host,'platform_subdomain','active',true,n,n,n),(gen_random_uuid(),otherst,otherhost,'platform_subdomain','active',true,n,n,n);
 INSERT INTO saas.domains(id,store_id,normalized_hostname,domain_type,status,canonical,cache_version,created_at,updated_at) VALUES(gen_random_uuid(),st,host,'platform_subdomain','active',true,1,n,n),(gen_random_uuid(),otherst,otherhost,'platform_subdomain','active',true,1,n,n);
 FOREACH store IN ARRAY ARRAY[st,otherst]LOOP
  INSERT INTO saas.merchant_admin_records(id,store_id,record_kind,name,config,status,created_at,updated_at)VALUES(gen_random_uuid(),store,'contact_widget','İletişim',widget,'active',n,n),(gen_random_uuid(),store,'restock_alerts','Stok','{"schemaVersion":1,"enabled":true,"title":"Stok gelince haber ver","buttonLabel":"Haber ver"}','active',n,n),(gen_random_uuid(),store,'whatsapp_order_setting','WhatsApp',whatsapp,'active',n,n);
  INSERT INTO saas.store_engagement_campaigns(id,store_id,kind,name,enabled,config,created_by,updated_by,created_at,updated_at)VALUES(CASE WHEN store=st THEN capture ELSE gen_random_uuid()END,store,'cart_capture','Sepet',true,engagement,pr,pr,n,n),(CASE WHEN store=st THEN popup ELSE gen_random_uuid()END,store,'popup','Popup',true,engagement,pr,pr,n,n);
 END LOOP;
 SELECT * INTO r FROM saas.public_contact_widget_get(otherhost,n);IF r.outcome<>'found'OR r.result_payload->'config'<>'null'::jsonb THEN RAISE EXCEPTION 'TOOL264_UNLICENSED_WIDGET:%',r;END IF;
 SELECT * INTO r FROM saas.public_whatsapp_order_get(otherhost,n);IF r.outcome<>'found'OR r.result_payload IS NOT NULL THEN RAISE EXCEPTION 'TOOL264_UNLICENSED_WHATSAPP:%',r;END IF;
 SELECT * INTO r FROM saas.public_restock_alerts_get(otherhost,n);IF r.outcome<>'ok'OR r.result_payload->'config'<>'null'::jsonb THEN RAISE EXCEPTION 'TOOL264_UNLICENSED_RESTOCK:%',r;END IF;
 SELECT * INTO r FROM saas.store_engagement_public_settings(otherhost,n);IF r.result_payload->'cartCapture'<>'null'::jsonb OR jsonb_array_length(r.result_payload->'popups')<>1 THEN RAISE EXCEPTION 'TOOL264_POPUP_BOUNDARY:%',r;END IF;
 SELECT * INTO r FROM saas.email_marketing_contact_capture(otherhost,repeat('a',64),n,gen_random_uuid(),capture,'a@example.test',NULL,false,repeat('b',64));IF r.outcome<>'campaign_unavailable'THEN RAISE EXCEPTION 'TOOL264_CAPTURE_GATE:%',r;END IF;
 IF saas.restock_enabled(otherst,n)OR saas.restock_enabled(otherst)THEN RAISE EXCEPTION 'TOOL264_WORKER_GATE';END IF;
 INSERT INTO store_tool_public_checks VALUES('new growth subscriptions do not silently grant standalone tools; popup package rights remain');
 INSERT INTO saas.store_tool_licenses(store_id,tool_key,source,purchase_id,granted_at)SELECT st,k,'grandfathered',NULL,n FROM unnest(ARRAY['contact_widget','whatsapp_ordering','cart_capture','restock','order_bump'])k;
 SELECT * INTO r FROM saas.public_contact_widget_get(host,n);IF r.result_payload->'config'<>widget THEN RAISE EXCEPTION 'TOOL264_FREE_WIDGET:%',r;END IF;
 SELECT * INTO r FROM saas.public_whatsapp_order_get(host,n);IF r.result_payload->'config'<>whatsapp THEN RAISE EXCEPTION 'TOOL264_FREE_WHATSAPP:%',r;END IF;
 SELECT * INTO r FROM saas.public_restock_alerts_get(host,n);IF r.result_payload->'config'->'enabled'<>'true'::jsonb THEN RAISE EXCEPTION 'TOOL264_FREE_RESTOCK:%',r;END IF;
 SELECT * INTO r FROM saas.store_engagement_public_settings(host,n);IF r.result_payload->'cartCapture'->>'id'<>capture::text OR r.result_payload->'popups'<>'[]'::jsonb THEN RAISE EXCEPTION 'TOOL264_FREE_CAPTURE:%',r;END IF;
 INSERT INTO store_tool_public_checks VALUES('licensed free subscriptions use their tools without acquiring unrelated popup entitlement');
 PERFORM set_config('saas.inventory.source_marker','catalog_adjustment',true);PERFORM set_config('saas.inventory.source_id',gen_random_uuid()::text,true);PERFORM set_config('saas.inventory.source_time',n::text,true);
 INSERT INTO saas.products(id,store_id,slug,title,status,currency,created_at,updated_at)VALUES(p1,st,'source-tool','Kaynak','active','TRY',n,n),(p2,st,'offered-tool','Öneri','active','TRY',n,n);
 INSERT INTO saas.product_variants(id,store_id,product_id,title,price_cents,stock_tracking,stock_quantity,status,created_at,updated_at)VALUES(v1,st,p1,'Kaynak',10000,true,10,'active',n,n),(v2,st,p2,'Öneri',2500,true,10,'active',n,n),(v3,st,p2,'Stoksuz',3000,true,0,'active',n,n);
 INSERT INTO saas.storefront_carts VALUES(cart,st,'active',1,n+interval '1 day',n,n);INSERT INTO saas.storefront_cart_credentials VALUES(cart,st,'qa264',repeat('a',64),n+interval '1 day');INSERT INTO saas.storefront_cart_items(cart_id,store_id,product_id,variant_id,quantity,unit_price_cents,position,created_at,updated_at)VALUES(cart,st,p1,v1,1,10000,0,n,n);
 INSERT INTO saas.order_bump_settings(store_id,version,config,created_by,updated_by,created_at,updated_at)VALUES(st,1,saas.order_bump_default_config()||jsonb_build_object('enabled',true,'rules',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'name','Öneri','enabled',true,'productIds','[]'::jsonb,'categoryIds','[]'::jsonb,'minSubtotalCents',NULL,'maxSubtotalCents',NULL,'variantIds',jsonb_build_array(v2)))),pr,pr,n,n);
 SELECT * INTO r FROM saas.order_bump_public_offers(host,n,creds,'side_cart');IF jsonb_array_length(r.result_payload->'offers')<>1 OR r.result_payload->'offers'->0->>'variantId'<>v2::text THEN RAISE EXCEPTION 'TOOL264_FREE_BUMP:%',r;END IF;
 SELECT * INTO r FROM saas.order_bump_public_offers(otherhost,n,creds,'side_cart');IF r.result_payload->'offers'<>'[]'::jsonb THEN RAISE EXCEPTION 'TOOL264_FOREIGN_BUMP:%',r;END IF;
 SELECT * INTO r FROM saas.email_marketing_contact_capture(host,repeat('a',64),n,op,capture,'a@example.test',NULL,false,repeat('b',64));IF r.outcome<>'captured'THEN RAISE EXCEPTION 'TOOL264_FREE_CONTACT:%',r;END IF;receipt:=r.result_payload;
 SELECT * INTO r FROM saas.email_marketing_contact_capture(host,repeat('a',64),n,op,capture,'a@example.test',NULL,false,repeat('b',64));IF r.outcome<>'replayed'OR r.result_payload<>receipt THEN RAISE EXCEPTION 'TOOL264_CONTACT_REPLAY:%',r;END IF;
 INSERT INTO store_tool_public_checks VALUES('free-plan recommendation uses canonical variant and cart; capture records once and replays');
 SELECT * INTO r FROM saas.restock_subscribe(host,v3,'stock@example.test',repeat('c',64),repeat('d',43),repeat('e',43),n);IF r.outcome<>'ok'THEN RAISE EXCEPTION 'TOOL264_SUBSCRIBE:%',r;END IF;
 SELECT * INTO r FROM saas.restock_claim(n,'tools264',25);IF jsonb_array_length(r.result_payload)<>1 THEN RAISE EXCEPTION 'TOOL264_STOCK_CLAIM:%',r;END IF;job:=r.result_payload->0;jobid:=(job->>'id')::uuid;lease:=(job->>'leaseId')::uuid;
 SELECT * INTO r FROM saas.restock_authorize(jobid,lease,'tools264',n);IF r.result_payload->>'kind'<>'confirmation'THEN RAISE EXCEPTION 'TOOL264_STOCK_AUTH:%',r;END IF;
 UPDATE saas.subscriptions SET status='inactive',updated_at=transaction_timestamp()WHERE store_id=st;
 SELECT * INTO r FROM saas.restock_authorize(jobid,lease,'tools264',n);IF r.result_payload IS NOT NULL THEN RAISE EXCEPTION 'TOOL264_STOCK_INACTIVE_SEND:%',r;END IF;
 SELECT * INTO r FROM saas.restock_claim(n+interval '2 minutes','tools264',25);IF r.result_payload<>'[]'::jsonb THEN RAISE EXCEPTION 'TOOL264_STOCK_INACTIVE_CLAIM:%',r;END IF;
 UPDATE saas.subscriptions SET status='active',updated_at=transaction_timestamp()WHERE store_id=st;
 SELECT * INTO r FROM saas.restock_manage(host,repeat('e',43),'cancel',n+interval '3 minutes');IF r.outcome<>'ok'THEN RAISE EXCEPTION 'TOOL264_CANCEL:%',r;END IF;
 IF NOT EXISTS(SELECT 1 FROM saas.restock_subscriptions WHERE store_id=st AND state='cancelled')THEN RAISE EXCEPTION 'TOOL264_CANCEL_STATE';END IF;
 INSERT INTO store_tool_public_checks VALUES('stock delivery requires active subscription at claim and before send; cancellation remains available');
 UPDATE saas.merchant_admin_records SET config=jsonb_set(config,'{hidePrices}','true'),updated_at=transaction_timestamp(),version=version+1 WHERE store_id IN(st,otherst)AND record_kind='whatsapp_order_setting';
 IF saas.whatsapp_commerce_allowed_258(host,n,'checkout','[]',NULL,NULL,NULL,NULL)OR NOT saas.whatsapp_commerce_allowed_258(otherhost,n,'checkout','[]',NULL,NULL,NULL,NULL)THEN RAISE EXCEPTION 'TOOL264_CHECKOUT_POLICY';END IF;
 IF NOT saas.google_merchant_whatsapp_catalog_only(st)OR saas.google_merchant_whatsapp_catalog_only(otherst)THEN RAISE EXCEPTION 'TOOL264_MERCHANT_POLICY';END IF;
 INSERT INTO store_tool_public_checks VALUES('WhatsApp public, native checkout and Merchant restrictions share licensed store authority');
END $test$;
SELECT jsonb_build_object('storeToolPublicChecks',jsonb_agg(name ORDER BY name),'passed',count(*))FROM store_tool_public_checks;
ROLLBACK;
